package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.CustomerContact.*;
import cn.mop.domain.contact.CustomerContactRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
/** Existing authorized identities/tenants only. Own synthetic contacts are archived after each case; no role/grant mutation. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresCustomerContactIntegrationTest {
    static final String A="55000000-0000-4000-8000-000000000001",B="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresCustomerContactRepository contacts;static String admin,tadmin,viewer,engineer,baseline;
    final List<Entry> owned=new ArrayList<>();
    @BeforeAll static void connect()throws Exception{String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);contacts=new PostgresCustomerContactRepository(pool,platform);admin=actor("padmin",true);tadmin=actor("tadmin",false);viewer=actor("viewer",false);engineer=actor("msp",false);assertEquals(List.of(),contacts.readinessProblems());baseline=baseline(B);}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role,boolean both)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT m.user_id::text FROM public.mop_membership m JOIN public.mop_user u ON u.id=m.user_id WHERE m.tenant_id=?::uuid AND m.role_code=? AND m.active AND u.active"+(both?" AND EXISTS(SELECT 1 FROM public.mop_membership b WHERE b.tenant_id=?::uuid AND b.user_id=m.user_id AND b.active)":"")+" ORDER BY m.user_id LIMIT 1")){s.setString(1,A);s.setString(2,role);if(both)s.setString(3,B);try(var r=s.executeQuery()){assertTrue(r.next());return r.getString(1);}}}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Access admin(){return access(admin,B);}
    static CustomerContact decision(String name){return new CustomerContact(name,Set.of(Role.DECISION_MAKER),null,null,null,null,null,true);}
    static CustomerContact reporter(String name){return new CustomerContact(name,Set.of(Role.REPORTER),null,"synthetic@example.test",null,Set.of(),new QuietWindow(false,null,null),true);}
    static JsonNode json(Object value){try{return mapper.readTree(mapper.writeValueAsBytes(value));}catch(Exception failure){throw new IllegalStateException(failure);}}
    static Object command(Access a,String id,String route,String key,String hash,Supplier<Object> action){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->contacts.authorizeWrite(a,id),action);}
    static String baseline(String tenant){Access a=access(admin,tenant);Object value=command(a,null,"POST /integration/customer-contacts/baseline","owned-contact-baseline-v1","a".repeat(64),()->contacts.create(a,0,decision("SYNTHETIC_CONTACT_REPOSITORY_BASELINE")));String id=json(value).path("id").asText();assertFalse(id.isBlank());Entry current=contacts.get(a,id);assertEquals("SYNTHETIC_CONTACT_REPOSITORY_BASELINE",current.facts().name());assertEquals(admin,current.createdBy());return id;}
    Entry create(CustomerContact facts){return create(admin(),facts);}
    Entry create(Access a,CustomerContact facts){Entry value=(Entry)command(a,null,"POST /integration/customer-contacts",UUID.randomUUID().toString(),"b".repeat(64),()->contacts.create(a,0,facts));owned.add(value);return value;}
    Entry update(Access a,Entry before,CustomerContact facts){return (Entry)command(a,before.id(),"PATCH /integration/customer-contacts/"+before.id(),UUID.randomUUID().toString(),"c".repeat(64),()->contacts.update(a,before.id(),before.version(),facts));}
    Entry archive(Access a,Entry before){return (Entry)command(a,before.id(),"POST /integration/customer-contacts/"+before.id()+"/archive",UUID.randomUUID().toString(),"d".repeat(64),()->contacts.archive(a,before.id(),before.version()));}
    Entry restore(Access a,Entry before,CustomerContact facts){return (Entry)command(a,before.id(),"POST /integration/customer-contacts/"+before.id()+"/restore",UUID.randomUUID().toString(),"e".repeat(64),()->contacts.restore(a,before.id(),before.version(),facts));}
    static long count(String tenant,String sql)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement(sql)){s.setString(1,tenant);try(var r=s.executeQuery()){assertTrue(r.next());return r.getLong(1);}}}
    static long decisions(String tenant)throws SQLException{return count(tenant,"SELECT count(*) FROM public.mop_customer_contact h JOIN public.mop_customer_contact_revision r ON r.tenant_id=h.tenant_id AND r.contact_id=h.id AND r.version=h.version WHERE h.tenant_id=?::uuid AND r.enabled AND NOT r.archived AND 'DECISION_MAKER'=ANY(r.roles)");}
    @BeforeEach void knownBaseline()throws Exception{Entry e=contacts.get(admin(),baseline);assertFalse(e.archived());assertTrue(e.facts().enabledDecisionMaker());}
    @AfterEach void restoreOnlyOwnedSamples(){if(pool==null||baseline==null)return;Access a=admin();Entry current=contacts.get(a,baseline);if(current.archived())restore(a,current,decision("SYNTHETIC_CONTACT_REPOSITORY_BASELINE"));else if(!current.facts().enabledDecisionMaker()||!current.facts().name().equals("SYNTHETIC_CONTACT_REPOSITORY_BASELINE"))update(a,current,decision("SYNTHETIC_CONTACT_REPOSITORY_BASELINE"));for(Entry row:owned){Access own=access(admin,row.tenantId());Entry now=contacts.get(own,row.id());assertTrue(now.facts().name().startsWith("SYNTHETIC_"));if(!now.archived())archive(own,now);}}
    @Test void createAndIndependentReadPreserveExplicitUnknownsAndQuietDeclarations(){var f=new CustomerContact("SYNTHETIC_资料😀",Set.of(Role.REPORTER,Role.TECHNICAL_CONTACT),"+8613800000000","Example+tag@example.test","SYNTHETIC_USER",Set.of(Priority.P1,Priority.P4),new QuietWindow(null,null,null),true);Entry e=create(f);assertEquals(f,contacts.get(admin(),e.id()).facts());assertEquals(1,e.version());assertFalse(e.archived());assertNull(e.facts().deliveryEligible());assertEquals("CONFIG_PENDING",e.facts().notificationRoutingStatus());}
    @Test void revisionCasAndOriginalCreatedTimeKeepHistoryImmutable(){Entry one=create(reporter("SYNTHETIC_revision"));Entry two=update(admin(),one,new CustomerContact("SYNTHETIC_revision_2",Set.of(Role.REPORTER),null,null,null,null,new QuietWindow(true,LocalTime.of(22,0),LocalTime.of(7,0)),false));assertEquals(2,two.version());assertEquals(one.createdAt(),two.createdAt());assertEquals(409,assertThrows(DomainException.class,()->update(admin(),one,one.facts())).status);var history=contacts.history(admin(),one.id(),10,null);assertEquals(List.of(2L,1L),history.stream().map(Revision::version).toList());assertEquals(one.facts(),history.get(1).facts());assertEquals(List.of(1L),contacts.history(admin(),one.id(),10,2L).stream().map(Revision::version).toList());}
    @Test void archiveStopsEligibilityAndRestoreNeedsExplicitFacts(){Entry one=create(reporter("SYNTHETIC_archive"));Entry archived=archive(admin(),one);assertTrue(archived.archived());assertFalse(archived.facts().enabled());assertEquals(false,archived.facts().deliveryEligible());assertEquals(409,assertThrows(DomainException.class,()->update(admin(),archived,one.facts())).status);Entry restored=restore(admin(),archived,one.facts());assertFalse(restored.archived());assertTrue(restored.facts().enabled());assertEquals(3,restored.version());assertEquals(409,assertThrows(DomainException.class,()->restore(admin(),restored,one.facts())).status);}
    @Test void currentAuthorizationTenantAdminAllowedEngineerViewerDenied(){String baseA=baseline(A);assertTrue(contacts.get(access(admin,A),baseA).facts().enabledDecisionMaker());Entry e=create(access(tadmin,A),reporter("SYNTHETIC_tadmin"));assertEquals(tadmin,e.createdBy());for(String actor:List.of(engineer,viewer)){Access denied=access(actor,A);assertEquals(403,assertThrows(DomainException.class,()->contacts.get(denied,e.id())).status);assertEquals(403,assertThrows(DomainException.class,()->create(denied,reporter("SYNTHETIC_denied"))).status);}}
    @Test void authorizedForeignTenantResourceIs404WithoutChangingItsVersion(){Entry e=create(reporter("SYNTHETIC_foreign"));Access other=access(admin,A);assertEquals(404,assertThrows(DomainException.class,()->contacts.get(other,e.id())).status);assertEquals(404,assertThrows(DomainException.class,()->archive(other,e)).status);assertEquals(1,contacts.get(admin(),e.id()).version());}
    @Test void originalCreateReplayReturnsOriginalReceiptAfterCurrentArchive()throws Exception{Access a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/contact-replay";Object first=command(a,null,route,key,"a".repeat(64),()->contacts.create(a,0,reporter("SYNTHETIC_replay")));Entry row=(Entry)first;owned.add(row);archive(a,row);Object replay=command(a,null,route,key,"a".repeat(64),()->{throw new AssertionError("must not create twice");});assertEquals(json(first),json(replay));assertTrue(contacts.get(a,row.id()).archived());assertEquals(409,assertThrows(DomainException.class,()->command(a,null,route,key,"b".repeat(64),()->null)).status);Access stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->command(stale,null,route,key,"a".repeat(64),()->null)).status);}
    @Test void callbackDenialPrecedesCachedReceiptWithoutMutatingIdentity(){Access a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/contact-callback";Entry e=(Entry)command(a,null,route,key,"a".repeat(64),()->contacts.create(a,0,reporter("SYNTHETIC_callback")));owned.add(e);assertEquals(403,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,"a".repeat(64),a.permissionVersion(),()->{throw new DomainException(403,"ACTION_FORBIDDEN","Explicit isolated authorization callback denial");},()->null)).status);}
    @Test void downstreamFailureRollsBackContactHistoryAuditAndReceipt()throws Exception{Access a=admin();String key=UUID.randomUUID().toString(),name="SYNTHETIC_rollback_"+key;long before=count(B,"SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid");assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/contact-rollback",key,"a".repeat(64),()->{contacts.create(a,0,reporter(name));throw new IllegalStateException("Explicit rollback after real writes");}));assertTrue(contacts.list(a,name,View.ALL,10,null,null).isEmpty());assertEquals(before,count(B,"SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid"));}
    @Test void writesOutsideProtectedCommandFailBeforeDatabaseMutation(){assertThrows(IllegalStateException.class,()->contacts.create(admin(),0,reporter("SYNTHETIC_unprotected")));assertThrows(IllegalStateException.class,()->contacts.authorizeWrite(admin(),null));}
    @Test void unicodeLiteralQueryStablePaginationAndArchivedFilter(){String marker="SYNTHETIC_PAGE_"+UUID.randomUUID();for(int i=0;i<12;i++)create(reporter(marker+"_"+i));var page=contacts.list(admin(),marker,View.CURRENT,10,null,null);assertEquals(10,page.size());Entry last=page.get(9);var next=contacts.list(admin(),marker,View.CURRENT,10,last.createdAt(),last.id());assertEquals(2,next.size());var ids=new HashSet<String>();page.forEach(e->assertTrue(ids.add(e.id())));next.forEach(e->assertTrue(ids.add(e.id())));Entry literal=create(reporter("SYNTHETIC_汉字_%_İ"));assertEquals(List.of(literal.id()),contacts.list(admin(),"汉字_%",View.CURRENT,10,null,null).stream().map(Entry::id).toList());archive(admin(),literal);assertTrue(contacts.list(admin(),"汉字_%",View.CURRENT,10,null,null).isEmpty());assertTrue(contacts.list(admin(),"汉字_%",View.ARCHIVED,100,null,null).stream().anyMatch(e->e.id().equals(literal.id())));}
    @Test void invalidBoundsAndStalePermissionVersionFailClosed(){for(int limit:List.of(0,102))assertEquals(400,assertThrows(DomainException.class,()->contacts.list(admin(),"",View.CURRENT,limit,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->contacts.list(admin(),"",View.CURRENT,10,Instant.now(),null)).status);Access a=admin();assertEquals(401,assertThrows(DomainException.class,()->contacts.get(new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId()),baseline)).status);}
    @Test void finalOwnedDecisionCannotBeDisabledArchivedOrLoseRole()throws Exception{Assumptions.assumeTrue(decisions(B)==1,"Another decision maker exists; do not modify unrelated contacts");Entry e=contacts.get(admin(),baseline);for(int action=0;action<3;action++){final int choice=action;DomainException failure=assertThrows(DomainException.class,()->{if(choice==0)archive(admin(),e);else update(admin(),e,choice==1?new CustomerContact("SYNTHETIC_CONTACT_REPOSITORY_BASELINE",e.facts().roles(),null,null,null,null,null,false):reporter("SYNTHETIC_CONTACT_REPOSITORY_BASELINE"));});assertEquals("LAST_ENABLED_DECISION_MAKER",failure.code);}assertEquals(1,decisions(B));}
    @Test void twoIndependentCommandsCannotTogetherRemoveLastDecision()throws Exception{Assumptions.assumeTrue(decisions(B)==1,"Another decision maker exists; do not modify unrelated contacts");Entry first=contacts.get(admin(),baseline),second=create(decision("SYNTHETIC_parallel_decision"));ExecutorService executor=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Integer>> futures=new ArrayList<>();for(Entry row:List.of(first,second))futures.add(executor.submit(()->{start.await();try{archive(admin(),row);return 200;}catch(DomainException error){assertEquals("LAST_ENABLED_DECISION_MAKER",error.code);return error.status;}}));start.countDown();List<Integer> statuses=new ArrayList<>();for(var f:futures)statuses.add(f.get(20,TimeUnit.SECONDS));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);assertEquals(1,decisions(B));assertEquals(1,List.of(contacts.get(admin(),first.id()),contacts.get(admin(),second.id())).stream().filter(Entry::archived).count());}finally{executor.shutdownNow();}}
    @Test void sameVersionConcurrentUpdatesYieldOneSuccessAndOneConflict()throws Exception{Entry e=create(reporter("SYNTHETIC_parallel_version"));ExecutorService executor=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Integer>> futures=new ArrayList<>();for(int i=0;i<2;i++){int index=i;futures.add(executor.submit(()->{start.await();try{update(admin(),e,reporter("SYNTHETIC_parallel_version_"+index));return 200;}catch(DomainException error){return error.status;}}));}start.countDown();List<Integer> statuses=new ArrayList<>();for(var f:futures)statuses.add(f.get(20,TimeUnit.SECONDS));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);assertEquals(2,contacts.get(admin(),e.id()).version());assertEquals(2,contacts.history(admin(),e.id(),10,null).size());}finally{executor.shutdownNow();}}
    @Test void originalArchiveReceiptRemainsSeparateFromLaterRestoredCurrentState(){Entry one=create(reporter("SYNTHETIC_archive_replay"));Access a=admin();String route="POST /integration/contact-archive-replay/"+one.id(),key=UUID.randomUUID().toString();Object archived=command(a,one.id(),route,key,"a".repeat(64),()->contacts.archive(a,one.id(),one.version()));Entry restored=restore(a,(Entry)archived,one.facts());Object replay=command(a,one.id(),route,key,"a".repeat(64),()->{throw new AssertionError("No second archive");});assertEquals(json(archived),json(replay));assertEquals(3,restored.version());assertFalse(contacts.get(a,one.id()).archived());}
    static Map<String,String> identityFingerprint()throws SQLException{Map<String,String> result=new LinkedHashMap<>();try(var c=pool.getConnection();var s=c.createStatement()){for(String table:List.of("mop_user","mop_membership"))try(var r=s.executeQuery("SELECT encode(sha256(convert_to(COALESCE(string_agg(to_jsonb(t)::text,E'\\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') FROM public."+table+" t")){assertTrue(r.next());result.put(table,r.getString(1));}}return result;}
    @Test void contactMaintenanceNeverCreatesOrMutatesIdentityBindingsAndMemberships()throws Exception{var before=identityFingerprint();Entry one=create(reporter("SYNTHETIC_identity_unchanged"));Entry two=update(admin(),one,new CustomerContact(one.facts().name(),Set.of(Role.REPORTER,Role.DECISION_MAKER),null,null,"SYNTHETIC_NOT_AN_IDENTITY_GRANT",null,null,true));archive(admin(),two);assertEquals(before,identityFingerprint());}
    @Test void successfulReadonlyListDetailHistoryDoesNotAppendAudit()throws Exception{Entry one=create(reporter("SYNTHETIC_readonly"));long before=count(B,"SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid");contacts.get(admin(),one.id());contacts.list(admin(),"SYNTHETIC_readonly",View.ALL,10,null,null);contacts.history(admin(),one.id(),10,null);assertEquals(before,count(B,"SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid"));}

}
